    if (Array.isArray(x)) return x.map(function (v, j) { return tr(v, pref, i, sub.concat(j)); });
    if (x && typeof x === "object") { var o = {}; for (var k in x) o[k] = SKIP[k] ? x[k] : tr(x[k], pref, i, sub.concat(k)); return o; }
